def _projection(frame):
    context = frame['context']
    zoom = frame['zoom']
    power = 1
    # Non-overview views use quadratic x. Their 1.5 zoom adjustment is
    # introduced by an explicit transform, not by the initial zoom state.
    if context != 'overview':
        power = 2
        if frame.get('has_transform', False):
            zoom *= 1.5
    out = {}
    for key, points in frame['series'].items():
        out[key] = [[70 + 460 * zoom * x ** power + frame['pan_x'], 200 + 300 * zoom * (1 - y) + frame['pan_y']] for x, y in points]
    return out

def _chart(s):
    frame = {'context': 'overview', 'zoom': 1.0, 'pan_x': 0.0, 'pan_y': 0.0, 'has_transform': False, 'series': s['series']}
    brushes = []
    for e in s['events']:
        if e['kind'] == 'reset_scene':
            frame = {'context': 'overview', 'zoom': 1.0, 'pan_x': 0.0, 'pan_y': 0.0, 'has_transform': False, 'series': s['series']}
            brushes = []
        elif e['kind'] == 'set_view':
            frame['context'] = e['context']
        elif e['kind'] == 'set_transform':
            for key in ['zoom', 'pan_x', 'pan_y']:
                frame[key] = e[key]
            frame['has_transform'] = True
        elif e['kind'] == 'new_data':
            frame['series'] = e['series']
        elif e['kind'] == 'clear_selection':
            brushes = []
        elif e['kind'] == 'brush':
            brushes.append({'frame': frame.copy(), 'box': [min(e['x0'], e['x1']), min(e['y0'], e['y1']), max(e['x0'], e['x1']), max(e['y0'], e['y1'])], 'mode': e['mode']})
    selected = []
    for brush in brushes:
        points = _projection(brush['frame'])
        box = brush['box']
        hits = []
        for key, line in points.items():
            if any(box[0] <= x <= box[2] and box[1] <= y <= box[3] for x, y in line):
                hits.append(key)
        mode = brush['mode']
        if mode == 'replace':
            selected = hits[:]
        elif mode == 'add':
            selected = sorted(selected + [k for k in hits if k not in selected])
        elif mode == 'subtract':
            selected = [k for k in selected if k not in hits]
        else:
            selected = sorted([k for k in selected if k not in hits] + [k for k in hits if k not in selected])
    return {'projected': _projection(frame), 'selected_ids': sorted(selected), 'linked_counts': [int(key in selected) for key in sorted(s['series'])]}

def solve(state):
    return _chart(state)

def _physics(s):
    b = s['initial_body'].copy()
    gravity, dt, contacts, grounded, contact = (0.0, 1 / 60, 0, False, None)
    floor, wall = (s['floor'], s['wall'])
    for e in s['events']:
        kind = e['kind']
        if kind == 'reset_scene':
            b = s['initial_body'].copy()
            gravity, dt, contacts, grounded, contact = (0.0, 1 / 60, 0, False, None)
        elif kind == 'set_body':
            for key in ['x', 'y', 'vx', 'vy']:
                b[key] = e[key]
            grounded, contact = (False, None)
        elif kind == 'set_physics':
            gravity, dt = (e['gravity'], e['dt'])
        elif kind == 'advance':
            for _ in range(e['ticks']):
                grounded, contact = (False, None)
                b['vy'] += gravity * 1.5 * dt
                b['vx'] *= max(0, 1 - 0.04 * dt * 60)
                nx, ny = (b['x'] + b['vx'] * dt, b['y'] + b['vy'] * dt)
                if b['vx'] > 0 and b['x'] + b['width'] <= wall['x'] <= nx + b['width'] and b['y'] + b['height'] > wall['y'] and b['y'] < wall['y'] + wall['height']:
                    nx = wall['x'] - b['width']
                    b['vx'] = 0
                    contacts += 1
                    contact = 'wall'
                overlap = nx + b['width'] > floor['x'] and nx < floor['x'] + floor['width']
                if overlap and b['vy'] > 0 and b['y'] + b['height'] <= floor['y'] <= ny + b['height']:
                    ny = floor['y'] - b['height']
                    b['vy'] *= 0.6
                    b['vx'] *= 0.7
                    contacts += 1
                    contact, grounded = ('floor', b['vy'] == 0)
                elif overlap and b['vy'] < 0 and floor['y'] + floor['height'] <= b['y'] <= floor['y'] + floor['height'] + 9 and ny <= floor['y'] + floor['height']:
                    ny = floor['y'] + floor['height']
                    b['vy'] *= 0.6
                    contacts += 1
                    contact = 'floor'
                if overlap and b['vy'] == 0 and abs(ny + b['height'] - floor['y']) < 1e-7:
                    grounded, contact = (True, 'floor')
                b['x'], b['y'] = nx, ny
    return {'x': b['x'], 'y': b['y'], 'vx': b['vx'], 'vy': b['vy'], 'grounded': grounded, 'contact': contact, 'contacts': contacts}

def solve(state):
    return _physics(state)
